

import {AfterViewInit, Component, ElementRef, input, viewChild, output, signal, WritableSignal, Signal, ChangeDetectionStrategy} from '@angular/core';
import {debounceTime, Subject} from 'rxjs';

@Component({
    selector: 'rm-ng-range-slider',
    templateUrl: './rm-ng-range-slider.component.html',
    imports: [],
    changeDetection: ChangeDetectionStrategy.Eager,
    styleUrls: ['./rm-ng-range-slider.component.scss']
})
export class RmNgRangeSliderComponent implements AfterViewInit {
  readonly min = input<number>(0);
  readonly max = input<number>(100);
  readonly leftColor = input<string>('#3498db'); // Default left color
  readonly rightColor = input<string>('#e74c3c'); // Default right color
  readonly leftTooltipColor = input<string>('#333'); // Default tooltip color for the left
  readonly rightTooltipColor = input<string>('#e74c3c'); // Default tooltip color for the right
  readonly lowSlider = viewChild.required<ElementRef<HTMLDivElement>>('lowSlider');
  readonly rangeChanged = output<{
    low: number;
    high: number;
}>();
  lowValue:WritableSignal<number> = signal(25); // Default value for the left thumb
  highValue:WritableSignal<number> = signal(75); // Default value for the right thumb
  private rangeChangedSubject: Subject<{ low: number, high: number }> = new Subject<{ low: number, high: number }>();

  ngAfterViewInit(): void {
    this.updateSliderColors();
    // Subscribe to the debounced range change subject
    this.rangeChangedSubject.pipe(
      debounceTime(300) // Adjust debounce time as needed
    ).subscribe((range: { low: number, high: number }): void => {
      this.rangeChanged.emit(range);
    });
  }

  onLowThumbChange(event: Event): void {
    let value: number = (event.target as HTMLInputElement).valueAsNumber;
    // Ensure the new low value does not exceed the high value
    if (value > this.highValue()) {
      value = this.highValue();
    }

    this.lowValue.set(value);
    this.emitRange();
    this.updateSliderColors();
  }

  onHighThumbChange(event: Event): void {
    let value: number = (event.target as HTMLInputElement).valueAsNumber;
    // Ensure the new high value does not go below the low value
    if (value < this.lowValue()) {
      value = this.lowValue();
    }

    this.highValue.set(value);
    this.emitRange();
    this.updateSliderColors();
  }

  emitRange(): void {
    this.rangeChangedSubject.next({low: this.lowValue(), high: this.highValue()});
  }

  updateSliderColors(): void {
    const lowSlider = this.lowSlider().nativeElement;
    const percentLow: number =
      ((this.lowValue() - this.min()) / (this.max() - this.min())) * 100;
    const percentHigh: number =
      ((this.highValue() - this.min()) / (this.max() - this.min())) * 100;
    lowSlider.style.background = `linear-gradient(to right, ${this.leftColor()} ${percentLow}%, ${this.rightColor()} ${percentHigh}%)`;
  }
}
